INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sally-ditch', 'west', 'the-ditch-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-fen', 'south', 'the-fen-gut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mass-grave', 'south', 'the-grave-drain', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-willow-margin', 'east', 'the-willow-landing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-waste', 'south', 'the-waste-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-osier-beds', 'east', 'the-osier-landing', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-ditch-end', 'door', 'The Ditch End', 'The sally ditch stops being a ditch about a hundred paces out — the revetting gives up, the sides slump, and what was a channel becomes simply the wettest line across a wet field. A plank walk runs along it, three boards wide, greened over and still taking weight.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ditch-end', 'east', 'the-sally-ditch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ditch-end', 'west', 'the-fen-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-fen-edge', 'door', 'The Fen Edge', 'The last of the firm ground, and you feel exactly where it ends: your heel stops ringing and starts sucking. Ahead the fen opens flat to the horizon in reed and standing water, the black lines of old cuttings running through it, and no high ground anywhere in it at all.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fen-edge', 'east', 'the-ditch-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fen-edge', 'west', 'the-sinking-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fen-edge', 'south', 'the-open-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fen-edge', 'north', 'the-osier-landing', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-sinking-path', 'door', 'The Sinking Path', 'A raised way of dumped stone and brushwood laid straight out into the water, settling into it at its own pace — in places it stands a foot proud, in places you are wading it, and you cannot tell which is coming until you are in it.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sinking-path', 'east', 'the-fen-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sinking-path', 'west', 'the-drowned-hurdles', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-drowned-hurdles', 'door', 'The Drowned Hurdles', 'Hazel hurdles pegged edge to edge across the soft ground, a whole causeway of basketwork, and the water has taken it down a foot at a time. You are walking on the weave, and it flexes. In the clear water either side you can see three more layers of it going down, each one somebody''s answer to the last one sinking.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-hurdles', 'east', 'the-sinking-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-hurdles', 'west', 'the-tussock-ford', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-hurdles', 'south', 'the-rush-shore', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-tussock-ford', 'door', 'The Tussock Ford', 'The crossing here is a line of sedge tussocks, each one a footfall, each one rocking when you land on it. Between them the peat is bottomless — not deep, bottomless, the kind with no floor at all, only colder and colder water going down.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tussock-ford', 'east', 'the-drowned-hurdles', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tussock-ford', 'west', 'the-willow-landing', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-willow-landing', 'door', 'The Willow Landing', 'The causeway runs up out of the water onto a bank of grey willow, and there is a mooring ring set into the last stone of it — iron, thick as your thumb, still turning in its socket. Beyond the willows the ground firms and greens and the wood starts, close and cold.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-willow-landing', 'east', 'the-tussock-ford', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-willow-landing', 'west', 'the-willow-margin', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-fen-gut', 'door', 'The Fen Gut', 'Where the Black Fen drains, and it drains south: a slow gut of water a stride across, black to the eye and warm to the hand, with a bank of trodden peat alongside it wide enough to walk. The smell is the fortress''s own smell, carried out and thinned.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fen-gut', 'north', 'the-black-fen', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fen-gut', 'west', 'the-peat-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-peat-road', 'door', 'The Peat Road', 'A hauling way for peat carts, floated on brushwood and surfaced with the spoil off the cuttings, running dead straight west because there was nothing out here to make it bend. Ruts a foot deep, filled with water, holding the sky in two parallel lines.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-road', 'east', 'the-fen-gut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-road', 'west', 'the-open-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-road', 'south', 'the-peat-cuts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-peat-cuts', 'door', 'The Peat Cuts', 'Black rectangular pits, water-filled, cut in ranks with the turf-banks still stacked between them to dry. The peat here comes up with things in it: bog oak, and once in a while something that was not oak, tanned the colour of a saddle and perfectly preserved.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-cuts', 'north', 'the-peat-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-open-water', 'door', 'The Open Water', 'The reed gives out and there is simply water, a long shallow lake of it, and the way goes under and comes up again forty paces on. Knee-deep on a good day. There is no telling today from a good day until you are in it.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-open-water', 'east', 'the-peat-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-open-water', 'west', 'the-dead-alders', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-open-water', 'north', 'the-fen-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-dead-alders', 'door', 'The Dead Alders', 'A drowned alder wood, every tree standing and every tree dead, killed by the water rising round their roots a wet century ago. They have not fallen because there is no wind down here to push them. Under them it is dark enough at noon to want a light.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-alders', 'east', 'the-open-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-alders', 'west', 'the-rush-shore', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-rush-shore', 'door', 'The Rush Shore', 'Boards laid on trestles a foot above the water, running west through rush that stands higher than a man on both sides, so there is nothing to see but the boards and the sky. Things move in the rush alongside you, keeping pace, at about knee height.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-shore', 'east', 'the-dead-alders', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-shore', 'west', 'the-waste-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-shore', 'north', 'the-drowned-hurdles', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-shore', 'south', 'the-eel-traps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-eel-traps', 'door', 'The Eel Traps', 'A row of stakes out in the shallows with wicker traps still lashed to them, most collapsed, two not. Somebody worked this water hard enough to leave forty traps in it and never came back for one of them. Things move in the two that are still shut.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eel-traps', 'north', 'the-rush-shore', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-waste-foot', 'door', 'The Waste Foot', 'The boards end at a stone step and the ground comes up out of the water at last — sour and rushy and open, with one thorn tree standing out in it, bent the way the wind has always come from. You have seen that tree from the other side.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-waste-foot', 'east', 'the-rush-shore', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-waste-foot', 'north', 'the-far-waste', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-grave-drain', 'door', 'The Grave Drain', 'They cut a drain out of the bottom of the pit, because a pit that holds water does not settle and they needed it to settle. It runs south in a stone-lined channel you can walk bent-double, and it has not carried anything but rain in a long time. It is still the fastest way out of the Mass-Grave that is not back up the hill.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grave-drain', 'north', 'the-mass-grave', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grave-drain', 'west', 'the-quaking-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-quaking-flat', 'door', 'The Quaking Flat', 'A hundred paces of ground that is not ground: a raft of root and moss floating on water, and it moves under you in a slow swell that goes on moving after you stop. Step wrong and your leg goes through to the hip, into cold that has never once seen the sun.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quaking-flat', 'east', 'the-grave-drain', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quaking-flat', 'west', 'the-osier-landing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quaking-flat', 'north', 'the-heron-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-heron-stand', 'door', 'The Heron Stand', 'A gravel spit rising a foot out of the water, white with two centuries of heron lime and littered with the bones of everything they have ever eaten here. They are standing on it now, a dozen of them, absolutely still, and they do not go up as you come. They turn, and watch.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heron-stand', 'south', 'the-quaking-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-osier-landing', 'door', 'The Osier Landing', 'Cut willow in flooded rows, worked once for basket rods and long gone wild, and the water shallows out among them until it is only mud. There is no landing here really — just the point where you stop wading and start walking, with the wood''s withies standing ahead of you in the same water.', 0, 0, 'road', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-osier-landing', 'east', 'the-quaking-flat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-osier-landing', 'west', 'the-osier-beds', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-osier-landing', 'south', 'the-fen-edge', NULL);
